491|#[allow(clippy::too_many_arguments)]
492|pub(super) async fn provision(
493|    engine: &MutationEngine,
494|    store: &IdentitySledStore,
495|    actor: VerifiedIdentityActor<'_>,
496|    input: seed_provision::ProvisionInput,
497|    seal: seed_provision::ProvisionSealPin,
498|    _request_operation: &str,
499|    preflight: bool,
500|) -> Result<JsonValue> {
501|    canonical_key(&input.wireguard_pubkey)?;
502|    let sid = op_identity::session::derive_session_id(&input.wireguard_pubkey);
503|    ensure!(
504|        control_plane_chatbot_session_id().as_deref() == Some(sid.as_str())
505|            && configured_chatbot_key().as_deref() == Some(input.wireguard_pubkey.as_str()),
506|        "clean provision requires configured chatbot key"
507|    );
508|    let _lifecycle = store.lifecycle_lock(&sid).await.lock_owned().await;
509|    let _host = engine.lock_host_observation().await;
510|    seed_provision::admit(
511|        engine,
512|        store,
513|        actor.actor_id,
514|        actor.session_id,
515|        actor.genesis,
516|        &seal,
517|    )
518|    .await?;
519|    seed_provision::target_key_is_registered(&input.wireguard_pubkey).await?;
520|    let expected = load_revision(store, &sid).await?;
521|    let old = revision_sled(&expected)?;
522|    ensure!(
523|        old.as_ref()
524|            .is_some_and(|old| old.wireguard_pubkey == input.wireguard_pubkey)
525|            || deleted_for_provision(&expected) || fresh_for_provision(&expected),
526|        "clean provision requires the existing key or its explicit deletion tombstone"
527|    );
528|    if preflight {
529|        preflight_native_identity_effect().await?;
530|        let Some(old) = old else {
531|            seed_provision::admit(
532|                engine,
533|                store,
534|                actor.actor_id,
535|                actor.session_id,
536|                actor.genesis,
537|                &seal,
538|            )
539|            .await?;
540|            return Ok(
541|                serde_json::json!({"session_id":sid,"wireguard_pubkey":input.wireguard_pubkey,"expected_revision":expected.revision,"expected_revision_operation_id":expected.operation_id,
542|                "previous_instance":null,"previous_instance_etag":"","previous_native_instance":null}),
543|            );
544|        };
545|        let stored_instance = old
546|            .instance
547|            .context("previous native instance binding absent")?;
548|        let (native, etag) = delete_provision::retirement_native(&stored_instance)
549|            .await?
550|            .unwrap_or((JsonValue::Null, String::new()));
551|        seed_provision::admit(
552|            engine,
553|            store,
554|            actor.actor_id,
555|            actor.session_id,
556|            actor.genesis,
557|            &seal,
558|        )
559|        .await?;
560|        return Ok(
561|            serde_json::json!({"session_id":sid,"wireguard_pubkey":input.wireguard_pubkey,"expected_revision":expected.revision,"expected_revision_operation_id":expected.operation_id,
562|            "previous_instance":stored_instance,"previous_instance_etag":etag,"previous_native_instance":native}),
563|        );
564|    }
565|    ensure!(
566|        root_repair::valid_digest(&input.plan_sha256),
567|        "invalid adoption digest"
568|    );
