349|    fn invoke_with(
350|        &self,
351|        path: &str,
352|        arguments: Value,
353|        confirm_side_effects: bool,
354|        operation: impl FnOnce(&str, &str, &MethodDecl, Value) -> Result<Value>,
355|    ) -> Result<Value> {
356|        // Literal syntax preserves the canonical projected path: Path::components
357|        // would silently discard repeated separators and `.` components.
358|        let parts: Vec<_> = path.split('/').collect();
359|        ensure!(
360|            parts.len() == 5
361|                && parts[0] == "plugins"
362|                && parts[2] == "operations"
363|                && parts[4] == "call"
364|                && !parts[1].is_empty()
365|                && !parts[3].is_empty(),
366|            "expected mount-relative plugins/<encoded-plugin>/operations/<encoded-method>/call"
367|        );
368|        self.verify()?;
369|        let plugin = self.view["objects"]
370|            .as_object()
371|            .context("missing catalog")?
372|            .keys()
373|            .find(|name| encode_component(name) == parts[1])
374|            .context("path plugin is absent from pinned catalog")?;
375|        let schema = self.schema(plugin)?;
376|        let (method, decl) = schema
377|            .methods
378|            .iter()
379|            .find(|(name, _)| encode_component(name) == parts[3])
380|            .context("path operation is absent from pinned schema")?;
381|        dispatch::validate_arguments(decl, &arguments)?;
382|        crate::store::render_arguments(&arguments)
383|            .context("mounted operation arguments exceed 1 MiB")?;
384|        ensure!(
