394|    pub fn call(
395|        &self,
396|        plugin: &str,
397|        method: &str,
398|        decl: &MethodDecl,
399|        arguments: Value,
400|    ) -> Result<Value> {
401|        self.call_with(plugin, method, decl, arguments, |mut file, bytes| {
402|            file.write_all(bytes)
403|                .context("write mounted operation arguments")?;
404|            // fsync executes the complete call; even a denial retains its
405|            // exact diagnostic on this same handle. Never retry the write.
406|            let synced = file.sync_all();
407|            file.seek(SeekFrom::Start(0))
408|                .context("seek operation receipt")?;
409|            let body = read_bounded(file, MAX_RECEIPT).context("read operation receipt")?;
410|            terminal_receipt(&body, synced, plugin, method, decl)
411|        })
412|    }
