414|    fn call_with(
415|        &self,
416|        plugin: &str,
417|        method: &str,
418|        decl: &MethodDecl,
419|        arguments: Value,
420|        operation: impl FnOnce(File, &[u8]) -> Result<Value>,
421|    ) -> Result<Value> {
422|        dispatch::validate_arguments(decl, &arguments)?;
423|        let bytes = crate::store::render_arguments(&arguments)
424|            .context("mounted operation arguments exceed 1 MiB")?;
425|        self.verify()?;
426|        ensure!(
427|            self.view["objects"].get(plugin).is_some(),
428|            "plugin absent from mount"
429|        );
430|        let prefix = format!(
431|            "plugins/{}/operations/{}",
432|            encode_component(plugin),
433|            encode_component(method)
434|        );
435|        let mounted_decl: MethodDecl = serde_json::from_value(read_json(open_relative(
436|            &self.root,
437|            &format!("{prefix}/metadata.json"),
438|            false,
439|        )?)?)?;
440|        ensure!(
441|            mounted_decl == *decl,
442|            "mounted operation declaration changed"
443|        );
444|        ensure!(
445|            read_json(open_relative(
446|                &self.root,
447|                &format!("{prefix}/input.schema.json"),
448|                false
449|            )?)? == decl.args,
450|            "mounted operation argument schema changed"
451|        );
452|        let file = open_relative(&self.root, &format!("{prefix}/call"), true)?;
453|        self.verify()?;
454|        let result = operation(file, &bytes);
455|        // An effect may already have occurred: mismatch is an explicit failure,
456|        // never justification for automatically submitting the call again.
457|        self.verify()
458|            .context("mount changed during operation; do not retry automatically")?;
459|        result
460|    }
