41|/// Why a lungs call did not complete. Each stage maps to one errno so the
42|/// writer learns what failed from `close()`, and the full text goes to the
43|/// method's `error` file.
44|#[derive(Debug, thiserror::Error)]
45|pub enum LungsError {
46|    #[error("arguments are not a JSON value: {0}")]
47|    Json(String),
48|    #[error("arguments failed schema validation: {0}")]
49|    Arguments(String),
50|    #[error("no credential has been delivered to this identity: {0}")]
51|    Credential(String),
52|    #[error("identity registration refused: {0}")]
53|    Registration(String),
54|    #[error("call refused: {0}")]
55|    Refused(String),
56|    #[error("dispatch failed: {0}")]
57|    Transport(String),
58|    #[error("operation outcome is unknown; do not retry automatically: {0}")]
59|    OutcomeUnknown(String),
60|    #[error("operation contract unavailable: {0}")]
61|    Contract(String),
