64|impl LungsError {
65|    /// Correlation is retained even when the reply is lost. It never selects
66|    /// an identity or grants permission to the declared recovery operation.
67|    pub fn operation_id(&self) -> Option<&str> {
68|        let Self::OutcomeUnknown(message) = self else {
69|            return None;
70|        };
71|        let id = message
72|            .split_once("operation_id=")?
73|            .1
74|            .split(|character: char| character == ';' || character.is_whitespace())
75|            .next()?;
76|        uuid::Uuid::parse_str(id).ok()?;
77|        Some(id)
78|    }
