103|pub fn method_decl(
104|    store: &ObjectStore,
105|    target: &ProjectionTarget,
106|    plugin_id: &str,
107|    method_name: &str,
108|) -> Result<MethodDecl> {
109|    let object = match target {
110|        ProjectionTarget::View(id) => {
111|            let view = store.read_view(id)?;
112|            store.object_for_view(&view, plugin_id)?
113|        }
114|        ProjectionTarget::Workspace(id) => {
115|            let workspace = store.read_workspace(id)?;
116|            store.workspace_object(&workspace, plugin_id)?
117|        }
118|    };
119|    object
120|        .schema
121|        .methods
122|        .get(method_name)
123|        .cloned()
124|        .with_context(|| format!("method '{plugin_id}.{method_name}' is not schema-declared"))
125|}
