127|pub fn validate_arguments(method: &MethodDecl, arguments: &Value) -> Result<(), LungsError> {
128|    if method.returns.is_none() {
129|        return Err(LungsError::Contract("missing_result_contract".into()));
130|    }
131|    op_state_store::method_receipt::validate_json_size(
132|        arguments,
133|        op_state_store::method_receipt::MAX_METHOD_ARGUMENT_BYTES,
134|    )
135|    .map_err(|error| LungsError::Arguments(error.to_string()))?;
136|    jsonschema::Validator::new(&method.args)
137|        .map_err(|error| LungsError::Arguments(format!("sealed argument schema: {error}")))?
138|        .validate(arguments)
139|        .map_err(|error| LungsError::Arguments(error.to_string()))
140|}
