213|/// Dispatch as the identity that owns the lungs mount. Registration and the
214|/// call share one connection, so the bridge admits the call as that identity
215|/// and runs it through MutationEngine under the identity's own grants.
216|pub async fn call_as_identity(
217|    bus_address: &str,
218|    plugin_id: &str,
219|    method_name: &str,
220|    method: &MethodDecl,
221|    arguments: Value,
222|    credential: Vec<u8>,
223|) -> Result<CallReceipt, LungsError> {
224|    validate_arguments(method, &arguments)?;
225|    let operation_id = uuid::Uuid::new_v4().to_string();
226|    let connection = connect_bus(bus_address).await?;
227|    let bootstrap = tokio::time::timeout(
228|        LUNGS_NEGOTIATION_TIMEOUT,
229|        Proxy::new(
230|            &connection,
231|            PLUGIN_BUS_NAME,
232|            IDENTITY_OBJECT_PATH,
233|            IDENTITY_INTERFACE,
234|        ),
235|    )
236|    .await
237|    .map_err(|_| LungsError::Transport("identity bootstrap proxy timed out".into()))?
238|    .map_err(|error| LungsError::Transport(format!("identity bootstrap proxy: {error}")))?;
239|    let registered: bool = tokio::time::timeout(
240|        LUNGS_NEGOTIATION_TIMEOUT,
241|        bootstrap.call("RegisterCurrentSender", &(credential,)),
242|    )
243|    .await
244|    .map_err(|_| LungsError::Transport("identity registration timed out".into()))?
245|    .map_err(|error| match refusal(&error) {
246|        true => LungsError::Registration(error.to_string()),
247|        false => LungsError::Transport(format!("register: {error}")),
248|    })?;
249|    if !registered {
250|        return Err(LungsError::Registration(
251|            "bridge declined the credential".into(),
252|        ));
253|    }
254|    let result = plugin_call(
255|        &connection,
256|        plugin_id,
257|        method_name,
258|        &arguments,
259|        &operation_id,
260|    )
261|    .await?;
262|    receipt(plugin_id, method_name, method, result, &operation_id)
263|}
