292|            .build(),
293|    )
294|    .await
295|    .map_err(|_| LungsError::Transport("lungs socket negotiation timed out".into()))?
296|    .map_err(|error| LungsError::Transport(format!("lungs socket: {error}")))?;
297|    let lungs = tokio::time::timeout(
298|        LUNGS_NEGOTIATION_TIMEOUT,
299|        Proxy::new(
300|            &connection,
301|            PLUGIN_BUS_NAME,
302|            LUNGS_OBJECT_PATH,
303|            LUNGS_INTERFACE,
304|        ),
305|    )
306|    .await
307|    .map_err(|_| LungsError::Transport("lungs bind proxy timed out".into()))?
308|    .map_err(|error| LungsError::Transport(format!("lungs bind proxy: {error}")))?;
309|    let binding = tokio::time::timeout(LUNGS_NEGOTIATION_TIMEOUT, async {
310|        if session.is_empty() {
311|            lungs.call("BindCurrentContainer", &()).await
312|        } else {
