1728|/// Closed grant groups. A principal belongs to zero or more of these and
1729|/// inherits their capabilities. The names are not caller ids.
1730|pub const GRANT_GROUPS: &[&str] = &[
1731|    "$ROOT",
1732|    "$ADMIN",
1733|    "$SUPERADMIN",
1734|    "$EXTERNAL-MCP",
1735|    "$VENDOR",
1736|    "$GUEST",
1737|    "$AGENT-L1",
1738|    "$AGENT-L2",
1739|    "$AGENT-L3",
1740|    "$AGENT-L4",
1741|];
1742|
1743|fn legacy_footprint_key(key: &str) -> bool {
1744|    key.len() == 64 && key.bytes().all(|byte| byte.is_ascii_hexdigit())
1745|}
1746|
1747|fn grant_document_rejected(keys: impl Iterator<Item = impl AsRef<str>>) -> bool {
1748|    keys.into_iter().any(|key| {
1749|        let key = key.as_ref();
1750|        key == "*"
1751|            || legacy_footprint_key(key)
1752|            || (key.starts_with('$') && !GRANT_GROUPS.contains(&key))
1753|    })
1754|}
1755|
1756|/// Validate a durable grant document.
1757|///
1758|/// Principal entries keep an exact id and a `capabilities` array. Optional
1759|/// `groups` names must be members of [`GRANT_GROUPS`] and must exist as
1760|/// entries in the same document. A `*` key, a legacy 64-hex footprint key, or
1761|/// an unknown `$` name rejects the document.
1762|pub fn validate_grant_document(bytes: &[u8]) -> Result<(), String> {
1763|    let document: serde_json::Value =
1764|        serde_json::from_slice(bytes).map_err(|error| format!("grant document is not JSON: {error}"))?;
1765|    validated_grant_entries(&document).map(|_| ())
1766|}
1767|
1768|/// Share the complete document contract between publication and every reader.
1769|/// Runtime expansion must not salvage authority from a document the materializer
1770|/// would reject, including malformed entries for other principals or groups.
1771|fn validated_grant_entries(
1772|    document: &serde_json::Value,
1773|) -> Result<&serde_json::Map<String, serde_json::Value>, String> {
1774|    let entries = document
1775|        .as_object()
1776|        .ok_or_else(|| "grant document must be a JSON object keyed by principal_id or group".to_string())?;
1777|    if grant_document_rejected(entries.keys()) {
1778|        return Err(
1779|            "prohibited wildcard, legacy footprint, or unknown group key".to_string(),
1780|        );
1781|    }
1782|    for (key, entry) in entries {
1783|        let entry = entry
1784|            .as_object()
1785|            .ok_or_else(|| format!("grant entry for {key} must be an object"))?;
1786|        let capabilities = entry
1787|            .get("capabilities")
1788|            .and_then(serde_json::Value::as_array)
1789|            .ok_or_else(|| format!("grant entry for {key} must own a capabilities array"))?;
1790|        let mut unique = std::collections::HashSet::with_capacity(capabilities.len());
1791|        for capability in capabilities {
1792|            let capability = capability
1793|                .as_str()
1794|                .ok_or_else(|| format!("grant entry for {key} contains a non-string capability"))?;
1795|            if capability.trim().is_empty() {
1796|                return Err(format!("grant entry for {key} contains an empty capability"));
1797|            }
1798|            if !unique.insert(capability) {
1799|                return Err(format!(
1800|                    "grant entry for {key} repeats capability {capability}"
1801|                ));
1802|            }
1803|        }
1804|        if let Some(alias) = entry.get("display_alias")
1805|            && !alias.is_string()
1806|        {
1807|            return Err(format!("display_alias for {key} must be a string"));
1808|        }
1809|        if key.starts_with('$') {
1810|            if entry.contains_key("groups") {
1811|                return Err(format!("group {key} cannot belong to another group"));
1812|            }
1813|            continue;
1814|        }
1815|        if key.is_empty() {
1816|            return Err("grant document contains an empty principal_id".to_string());
1817|        }
1818|        if let Some(groups) = entry.get("groups") {
1819|            let groups = groups
1820|                .as_array()
1821|                .ok_or_else(|| format!("groups for {key} must be an array"))?;
1822|            let mut seen = std::collections::HashSet::with_capacity(groups.len());
1823|            for group in groups {
1824|                let group = group
1825|                    .as_str()
1826|                    .ok_or_else(|| format!("groups for {key} contains a non-string"))?;
1827|                if !GRANT_GROUPS.contains(&group) || !entries.contains_key(group) {
1828|                    return Err(format!("principal {key} references unknown group {group}"));
1829|                }
1830|                if !seen.insert(group) {
1831|                    return Err(format!("principal {key} repeats group {group}"));
1832|                }
1833|            }
1834|        }
1835|    }
1836|    Ok(entries)
1837|}
1838|
1839|/// Load the capabilities granted to one registered principal.
1840|///
1841|/// The JSON document is keyed by exact `principal_id` plus `$` group entries.
1842|/// A principal inherits every capability of the groups named in its `groups`
1843|/// array, then its own `capabilities`. Missing, malformed, or unreadable grant
1844|/// state fails closed.
1845|pub fn load_capability_grants(principal_id: &str) -> std::collections::HashSet<String> {
1846|    let path = std::env::var("OP_GRANTS_PATH")
1847|        .unwrap_or_else(|_| "/dev/shm/opdbus/capability-grants.json".to_string());
1848|    let Ok(bytes) = std::fs::read(path) else {
1849|        return std::collections::HashSet::new();
1850|    };
1851|    let Ok(document) = serde_json::from_slice::<serde_json::Value>(&bytes) else {
1852|        return std::collections::HashSet::new();
1853|    };
1854|    capabilities_for_principal(&document, principal_id)
1855|}
1856|
1857|/// Parse one principal's grants from a document of principals and groups.
1858|///
1859|/// The complete document must pass the same validation used by the grant
1860|/// materializer. Looking up a group name returns nothing: groups are not callers.
1861|pub(crate) fn capabilities_for_principal(
1862|    document: &serde_json::Value,
1863|    principal_id: &str,
1864|) -> std::collections::HashSet<String> {
1865|    if principal_id.is_empty() || principal_id == "*" || principal_id.starts_with('$') {
1866|        return std::collections::HashSet::new();
1867|    }
1868|    let Ok(entries) = validated_grant_entries(document) else {
1869|        return std::collections::HashSet::new();
1870|    };
1871|    let Some(entry) = entries.get(principal_id) else {
1872|        return std::collections::HashSet::new();
1873|    };
1874|    let mut granted = std::collections::HashSet::new();
1875|    let Some(own) = entry.get("capabilities").and_then(serde_json::Value::as_array) else {
1876|        return std::collections::HashSet::new();
1877|    };
1878|    granted.extend(own.iter().filter_map(serde_json::Value::as_str).map(str::to_string));
1879|    let Some(groups) = entry.get("groups") else {
1880|        return granted;
1881|    };
1882|    let Some(groups) = groups.as_array() else {
1883|        return std::collections::HashSet::new();
1884|    };
1885|    for group in groups {
1886|        let Some(name) = group.as_str() else {
1887|            return std::collections::HashSet::new();
1888|        };
1889|        if !GRANT_GROUPS.contains(&name) {
1890|            return std::collections::HashSet::new();
1891|        }
1892|        let Some(capabilities) = entries
1893|            .get(name)
1894|            .and_then(|group_entry| group_entry.get("capabilities"))
1895|            .and_then(serde_json::Value::as_array)
1896|        else {
1897|            return std::collections::HashSet::new();
1898|        };
1899|        granted.extend(
1900|            capabilities
1901|                .iter()
1902|                .filter_map(serde_json::Value::as_str)
1903|                .map(str::to_string),
1904|        );
1905|    }
1906|    granted
1907|}","total_lines":1907,"file_size":75768,"truncated":false,"is_binary":false,"is_image":false,"not_found":false}

{"content":"1|//! Canonical method accountability envelope, independent of domain schemas.
2|//! The admitted plugin still owns the schema of `result`.
3|use serde::{Deserialize, Serialize};
4|use serde_json::Value;
5|
6|pub const MAX_METHOD_ARGUMENT_BYTES: usize = 1024 * 1024;
7|pub const MAX_METHOD_RECEIPT_BYTES: usize = 16 * 1024 * 1024;
8|
9|#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, schemars::JsonSchema)]
10|#[serde(deny_unknown_fields)]
11|pub struct MethodEventProof {
12|    #[schemars(range(min = 1))]
13|    pub event_id: u64,
14|    #[schemars(length(min = 32, max = 32), regex(pattern = "^[0-9a-f]{32}$"))]
15|    pub event_hash: String,
16|}
17|
18|#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, schemars::JsonSchema)]
19|#[serde(rename_all = "snake_case")]
20|pub enum MethodRecoveryStatus {
21|    Completed,
22|    Failed,
23|    Unknown,
24|    NotFound,
25|}
26|
27|#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
28|#[serde(deny_unknown_fields)]
29|pub struct GetMethodReceiptInput {
30|    #[schemars(
31|        length(min = 36, max = 36),
32|        regex(pattern = "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")
33|    )]
34|    pub operation_id: String,
35|}
36|
37|/// Caller-private recovery metadata, never a copy of a private domain result.
38|#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
39|#[serde(deny_unknown_fields)]
40|pub struct MethodReceiptRecovery {
41|    #[schemars(
42|        length(min = 36, max = 36),
43|        regex(pattern = "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")
44|    )]
45|    pub operation_id: String,
46|    pub status: MethodRecoveryStatus,
47|    pub plugin_id: Option<String>,
48|    pub method: Option<String>,
49|    pub attempt: Option<MethodEventProof>,
50|    pub terminal: Option<MethodEventProof>,
51|    pub result_digest: Option<String>,
52|}
53|
54|#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
55|#[serde(deny_unknown_fields)]
56|pub struct MethodExecutionReceipt {
57|    pub success: bool,
58|    pub operation_id: String,
59|    pub outcome: String,
60|    pub event_id: u64,
61|    pub event_hash: String,
62|    pub terminal_event_id: u64,
63|    pub terminal_event_hash: String,
64|    pub plugin_id: String,
65|    pub method: String,
66|    pub result: Value,
67|}
68|
69|pub fn valid_event_hash(hash: &str) -> bool {
70|    // ChainEvent::compute_hash delegates to event_chain::compute_hash, whose
71|    // persisted wire format is lowercase hexadecimal MD5 (32 characters).
72|    // This is an audit locator, not a plugin's BLAKE3 schema/content hash.
73|    hash.len() == 32
74|        && hash
75|            .bytes()
76|            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
77|}
78|
79|impl MethodExecutionReceipt {
80|    /// Check transport attribution and both durable audit references. This is
81|    /// not a grant or independent ledger lookup: the authenticated canonical
82|    /// transport supplies the proof; callers must keep their pinned identity.
83|    pub fn validate_attribution(&self, plugin: &str, method: &str) -> anyhow::Result<()> {
84|        anyhow::ensure!(
85|            self.success && self.outcome == "completed",
86|            "method outcome is not completed"
87|        );
88|        anyhow::ensure!(
89|            self.plugin_id == plugin && self.method == method,
90|            "method receipt attribution mismatch"
91|        );
92|        let operation = uuid::Uuid::parse_str(&self.operation_id)?;
93|        anyhow::ensure!(
94|            operation.to_string() == self.operation_id,
95|            "noncanonical operation id"
96|        );
97|        anyhow::ensure!(
98|            self.event_id > 0 && self.terminal_event_id > self.event_id,
99|            "method receipt event ordering invalid"
100|        );
101|        anyhow::ensure!(
102|            valid_event_hash(&self.event_hash) && valid_event_hash(&self.terminal_event_hash),
103|            "method receipt event proof invalid"
104|        );
105|        Ok(())
106|    }
107|}
108|
109|/// Bounded serialization avoids allocating a second unbounded payload merely
110|/// to measure a response. The backend remains responsible for its own buffers.
111|pub fn validate_json_size(value: &Value, limit: usize) -> anyhow::Result<()> {
112|    struct Budget(usize);
113|    impl std::io::Write for Budget {
114|        fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
115|            self.0 = self
116|                .0
117|                .checked_sub(bytes.len())
118|                .ok_or_else(|| std::io::Error::other("method document byte bound"))?;
119|            Ok(bytes.len())
120|        }
121|        fn flush(&mut self) -> std::io::Result<()> {
122|            Ok(())
123|        }
124|    }
125|    serde_json::to_writer(Budget(limit), value)?;
126|    Ok(())
127|}
128|
129|/// A missing output declaration cannot establish a verified domain result.
130|pub fn validate_method_result(schema: Option<&Value>, result: &Value) -> anyhow::Result<()> {
131|    validate_json_size(result, MAX_METHOD_RECEIPT_BYTES)?;
132|    let schema = schema.ok_or_else(|| anyhow::anyhow!("missing_result_contract"))?;
133|    let validator = jsonschema::validator_for(schema)?;
134|    validator.validate(result).map_err(|error| {
135|        anyhow::anyhow!(
136|            "method result violates declaration at {}",
137|            error.instance_path
138|        )
139|    })?;
140|    Ok(())
141|}
