154|#[tokio::main]
155|async fn main() -> Result<()> {
156|    let mut args = std::env::args_os().skip(1);
157|    let command = args
158|        .next()
159|        .and_then(|value| value.into_string().ok())
160|        .unwrap_or_default();
161|    let (source, target, ready) = paths();
162|
163|    match command.as_str() {
164|        "validate" => {
165|            let path = args
166|                .next()
167|                .map(PathBuf::from)
168|                .unwrap_or_else(|| source.clone());
169|            if args.next().is_some() {
170|                bail!("validate accepts at most one path");
171|            }
172|            validate_document(&fs::read(&path).with_context(|| path.display().to_string())?)?;
173|            println!("Valid");
174|        }
175|        "validate-audience" => {
176|            let path = args
177|                .next()
178|                .map(PathBuf::from)
179|                .context("validate-audience requires one path")?;
180|            if args.next().is_some() {
181|                bail!("validate-audience accepts exactly one path");
182|            }
183|            parse_audience_policy(&fs::read(&path).with_context(|| path.display().to_string())?)?;
184|            println!("Valid");
185|        }
186|        "validate-toolsets" => {
187|            let path = args
188|                .next()
189|                .map(PathBuf::from)
190|                .context("validate-toolsets requires one path")?;
191|            if args.next().is_some() {
192|                bail!("validate-toolsets accepts exactly one path");
193|            }
194|            parse_toolset_manifest(&fs::read(&path).with_context(|| path.display().to_string())?)?;
195|            println!("Valid");
196|        }
197|        "check" => {
198|            if args.next().is_some() {
199|                bail!("check accepts no arguments");
200|            }
201|            if check(&source, &target)? {
202|                println!("Fresh");
203|            } else {
204|                println!("Stale");
205|                std::process::exit(1);
206|            }
207|        }
208|        "once" => {
209|            if args.next().is_some() {
210|                bail!("once accepts no arguments");
211|            }
212|            println!("{:?}", reconcile(&source, &target, &ready)?);
213|        }
214|        "run" => {
215|            if args.next().is_some() {
216|                bail!("run accepts no arguments");
217|            }
218|            let mut last_message = String::new();
219|            loop {
220|                let message = match reconcile(&source, &target, &ready) {
221|                    Ok(ReconcileState::Fresh) => "Fresh".to_string(),
222|                    Ok(ReconcileState::Materialized) => "Grants materialized".to_string(),
223|                    Err(error) => format!("Fail-closed: {error:#}"),
224|                };
225|                if message != last_message {
226|                    eprintln!("grants materializer: {message}");
227|                    last_message = message;
228|                }
229|                tokio::select! {
230|                    _ = tokio::signal::ctrl_c() => break,
231|                    _ = tokio::time::sleep(Duration::from_secs(1)) => {}
232|                }
233|            }
234|        }
235|        _ => bail!(
236|            "unknown command '{command}'; expected run, check, once, validate [path], validate-audience <path>, or validate-toolsets <path>"
237|        ),
238|    }
239|    Ok(())
240|}
