206|impl LungsIdentity {
207|    fn new(
208|        engine: Arc<MutationEngine>,
209|        peer_uid: u32,
210|        peer: ProcessIdentity,
211|        peer_lifetime: PeerLifetime,
212|        host: Arc<ProcessIdentity>,
213|    ) -> Self {
214|        Self {
215|            engine,
216|            peer_uid,
217|            peer,
218|            peer_lifetime,
219|            host,
220|            binding: OnceLock::new(),
221|            bootstrap: tokio::sync::Mutex::new(()),
222|            bound: tokio::sync::Notify::new(),
223|        }
224|    }
225|
226|    fn is_host_root(&self) -> bool {
227|        host_root_allowed(self.peer_uid, &self.peer, &self.host)
228|    }
229|
230|    fn revalidate_peer(&self) -> Result<()> {
231|        self.peer_lifetime.revalidate(&self.peer)
232|    }
233|
234|    /// Resolution is performed for every PluginV1.Call. Native restart or
235|    /// replacement cannot inherit a connection, even with the same UID/name.
236|    pub async fn resolve(&self) -> Result<GhostbridgeIdentity, DbusIdentityError> {
237|        let binding = self.binding.get().ok_or(DbusIdentityError::NoBinding)?;
238|        let outcome = async {
239|            self.revalidate_peer()?;
240|            match binding {
241|                Binding::Host(_) => ensure!(self.is_host_root(), "host peer changed"),
242|                Binding::Container(pinned) => {
243|                    let sled = crate::identity_sled_dispatch::stored_session(
244|                        self.engine.as_ref(),
245|                        &pinned.session_id,
246|                    )
247|                    .await?
248|                    .context("identity binding unavailable")?;
249|                    let current = self.container_binding(&sled).await?;
250|                    ensure!(same_binding(pinned, &current), "container binding changed");
251|                }
252|            }
253|            self.revalidate_peer()?;
254|            let identity = authoritative_session_identity(
255|                self.engine.as_ref(),
256|                None,
257|                binding.session_id(),
258|                true,
259|            )
260|            .await
261|            .map_err(anyhow::Error::from)?;
262|            self.revalidate_peer()?;
263|            Ok(identity)
264|        };
265|        tokio::time::timeout(NEGOTIATION_TIMEOUT, outcome)
266|            .await
267|            .map_err(|_| DbusIdentityError::StaleBinding)?
268|            .map_err(|error| {
269|                tracing::warn!(%error, "lungs identity revalidation refused");
270|                DbusIdentityError::StaleBinding
271|            })
272|    }
