274|    async fn container_binding(&self, sled: &ContainerIdentitySled) -> Result<ContainerBinding> {
275|        self.revalidate_peer()?;
276|        ensure!(sled.active && sled.is_anchored(), "identity is not active");
277|        let stored = sled
278|            .instance
279|            .as_ref()
280|            .context("identity container unavailable")?;
281|        ensure!(
282|            crate::identity_sled_dispatch::identity_instance_matches(sled, stored),
283|            "identity container does not match"
284|        );
285|        let native_uuid = instance_uuid(stored)?;
286|        let native = IncusRootRepairBackend::local();
287|        let (metadata, _) = native.instance(&stored.name).await?;
288|        let current = IncusPlugin::instance_from_native_metadata(metadata)?;
289|        ensure!(
290|            current.name == stored.name
291|                && current.instance_type == "container"
292|                && current.status == "Running"
293|                && current.project.as_deref() == Some("default")
294|                && current.location.as_deref() == Some("none")
295|                && instance_uuid(&current)? == native_uuid
296|                && crate::identity_sled_dispatch::identity_instance_matches(sled, &current),
297|            "native identity container does not match"
298|        );
299|        let init_pid = native.instance_init_pid(&stored.name).await?;
300|        let init = ProcessIdentity::read(init_pid)?;
301|        ensure!(
302|            self.peer.same_namespaces(&init),
303|            "peer is outside identity container"
304|        );
305|        self.revalidate_peer()?;
306|        init.revalidate()?;
307|        // Close the native read/proc race before publishing this term.
