227|pub(super) fn trusted_plan_bytes_at(
228|    directory: &Path,
229|    session_id: &str,
230|    digest: &str,
231|    owner_uid: u32,
232|) -> Result<Vec<u8>> {
233|    anyhow::ensure!(
234|        valid_digest(digest),
235|        "plan_sha256 must be 64 lowercase hex digits"
236|    );
237|    let parsed = uuid::Uuid::parse_str(session_id).context("invalid own session ID")?;
238|    anyhow::ensure!(
239|        parsed.to_string() == session_id,
240|        "noncanonical own session ID"
241|    );
242|    anyhow::ensure!(directory.is_absolute(), "plan directory is not absolute");
243|    // Walk with held directory descriptors. Checking path strings first and
244|    // reopening the final pathname would permit ancestor replacement races.
245|    let root = CString::new("/")?;
246|    let root_fd = unsafe {
247|        nix::libc::open(
248|            root.as_ptr(),
249|            nix::libc::O_RDONLY
250|                | nix::libc::O_DIRECTORY
251|                | nix::libc::O_CLOEXEC
252|                | nix::libc::O_NOFOLLOW,
253|        )
254|    };
255|    anyhow::ensure!(root_fd >= 0, "cannot open trusted plan root");
256|    let mut dir = unsafe { File::from_raw_fd(root_fd) };
257|    for component in directory.components() {
258|        let Component::Normal(segment) = component else {
259|            anyhow::ensure!(
260|                matches!(component, Component::RootDir),
261|                "unsafe plan directory component"
262|            );
263|            continue;
264|        };
265|        let name = CString::new(segment.as_encoded_bytes())?;
266|        let fd = unsafe {
267|            nix::libc::openat(
268|                dir.as_raw_fd(),
269|                name.as_ptr(),
270|                nix::libc::O_RDONLY
271|                    | nix::libc::O_DIRECTORY
272|                    | nix::libc::O_CLOEXEC
273|                    | nix::libc::O_NOFOLLOW,
274|            )
275|        };
276|        anyhow::ensure!(fd >= 0, "trusted plan ancestor is absent or unsafe");
277|        let next = unsafe { File::from_raw_fd(fd) };
278|        let meta = next.metadata()?;
279|        anyhow::ensure!(
280|            meta.is_dir() && meta.uid() == owner_uid && meta.permissions().mode() & 0o022 == 0,
281|            "trusted plan ancestor is not owner-controlled"
282|        );
283|        dir = next;
284|    }
285|    let dir_meta = dir.metadata()?;
286|    anyhow::ensure!(
287|        dir_meta.permissions().mode() & 0o077 == 0,
288|        "root repair plan directory is not private"
289|    );
290|    let filename = CString::new(format!("{session_id}.json"))?;
291|    let fd = unsafe {
292|        nix::libc::openat(
293|            dir.as_raw_fd(),
294|            filename.as_ptr(),
295|            nix::libc::O_RDONLY | nix::libc::O_CLOEXEC | nix::libc::O_NOFOLLOW,
296|        )
297|    };
298|    anyhow::ensure!(fd >= 0, "root repair plan absent");
299|    let mut file = unsafe { File::from_raw_fd(fd) };
300|    let meta = file.metadata()?;
301|    anyhow::ensure!(
302|        meta.is_file()
303|            && meta.uid() == owner_uid
304|            && meta.permissions().mode() & 0o077 == 0
305|            && meta.len() <= MAX_PLAN_BYTES,
306|        "root repair plan is not a private bounded regular file"
307|    );
308|    let mut bytes = Vec::with_capacity(meta.len() as usize);
309|    file.by_ref()
310|        .take(MAX_PLAN_BYTES + 1)
311|        .read_to_end(&mut bytes)?;
312|    anyhow::ensure!(
313|        bytes.len() as u64 <= MAX_PLAN_BYTES,
314|        "root repair plan is oversized"
315|    );
316|    let actual = hex::encode(Sha256::digest(&bytes));
317|    anyhow::ensure!(actual == digest, "root repair plan digest mismatch");
318|    Ok(bytes)
319|}
