290|    /// Fresh discovery for native clients. These are the mounted declarations,
291|    /// not a parallel tool schema or an authority to execute the operations.
292|    pub fn describe(&self, selected_plugin: Option<&str>) -> Result<Value> {
293|        self.verify()?;
294|        let objects = self.view["objects"]
295|            .as_object()
296|            .context("missing catalog")?;
297|        if let Some(plugin) = selected_plugin {
298|            ensure!(
299|                objects.contains_key(plugin),
300|                "plugin absent from mounted catalog"
301|            );
302|        }
303|        let mut methods = Vec::new();
304|        // Account for the envelope and separators as well as declarations.
305|        let mut remaining = MAX_DOCUMENT as usize - 32;
306|        for plugin in objects
307|            .keys()
308|            .filter(|plugin| selected_plugin.is_none_or(|selected| selected == plugin.as_str()))
309|        {
310|            let schema = self.schema(plugin)?;
311|            let mut declarations: Vec<_> = schema.methods.into_iter().collect();
312|            declarations.sort_by(|left, right| left.0.cmp(&right.0));
313|            for (method, declaration) in declarations {
314|                let descriptor = serde_json::json!({
315|                    "plugin_id": plugin,
316|                    "method": method,
317|                    "path": format!("plugins/{}/operations/{}/call",
318|                        encode_component(plugin), encode_component(&method)),
319|                    "declaration": declaration,
320|                });
321|                let size = serde_json::to_vec(&descriptor)?.len();
322|                remaining = remaining
323|                    .checked_sub(size + 1)
324|                    .context("mounted operation discovery exceeds 16 MiB")?;
325|                methods
326|                    .try_reserve(1)
327|                    .context("allocate operation discovery")?;
328|                methods.push(descriptor);
329|            }
330|        }
331|        self.verify()?;
332|        Ok(serde_json::json!({"methods": methods}))
333|    }
