463|fn terminal_receipt(
464|    body: &str,
465|    synced: std::io::Result<()>,
466|    plugin: &str,
467|    method: &str,
468|    decl: &MethodDecl,
469|) -> Result<Value> {
470|    let value: Value =
471|        serde_json::from_str(body).context("missing or malformed terminal operation receipt")?;
472|    if value.get("error").is_some() {
473|        ensure!(
474|            value["plugin"] == plugin && value["method"] == method,
475|            "operation diagnostic attribution mismatch"
476|        );
477|        return Err(MountedDiagnostic(value).into());
478|    }
479|    ensure!(
480|        value["plugin_id"] == plugin && value["method"] == method,
481|        "operation receipt attribution mismatch"
482|    );
483|    synced.context("operation fsync failed without a terminal diagnostic")?;
484|    ensure!(
485|        value["subid"] == decl.subid
486|            && value["required_capability"] == serde_json::to_value(&decl.required_capability)?
487|            && value["side_effect"] == serde_json::to_value(decl.side_effect)?
488|            && value["idempotent"] == decl.idempotent,
489|        "operation receipt contract mismatch"
490|    );
491|    ensure!(
492|        value.get("result").is_some(),
493|        "terminal operation receipt has no result"
494|    );
495|    dispatch::validate_engine_receipt(plugin, method, decl, &value["result"])?;
496|    Ok(value)
