1756|/// Validate a durable grant document.
1757|///
1758|/// Principal entries keep an exact id and a `capabilities` array. Optional
1759|/// `groups` names must be members of [`GRANT_GROUPS`] and must exist as
1760|/// entries in the same document. A `*` key, a legacy 64-hex footprint key, or
1761|/// an unknown `$` name rejects the document.
1762|pub fn validate_grant_document(bytes: &[u8]) -> Result<(), String> {
1763|    let document: serde_json::Value =
1764|        serde_json::from_slice(bytes).map_err(|error| format!("grant document is not JSON: {error}"))?;
