1768|/// Share the complete document contract between publication and every reader.
1769|/// Runtime expansion must not salvage authority from a document the materializer
1770|/// would reject, including malformed entries for other principals or groups.
1771|fn validated_grant_entries(
1772|    document: &serde_json::Value,
1773|) -> Result<&serde_json::Map<String, serde_json::Value>, String> {
1774|    let entries = document
1775|        .as_object()
1776|        .ok_or_else(|| "grant document must be a JSON object keyed by principal_id or group".to_string())?;
1777|    if grant_document_rejected(entries.keys()) {
1778|        return Err(
1779|            "prohibited wildcard, legacy footprint, or unknown group key".to_string(),
1780|        );
1781|    }
1782|    for (key, entry) in entries {
1783|        let entry = entry
1784|            .as_object()
1785|            .ok_or_else(|| format!("grant entry for {key} must be an object"))?;
1786|        let capabilities = entry
1787|            .get("capabilities")
1788|            .and_then(serde_json::Value::as_array)
1789|            .ok_or_else(|| format!("grant entry for {key} must own a capabilities array"))?;
1790|        let mut unique = std::collections::HashSet::with_capacity(capabilities.len());
1791|        for capability in capabilities {
1792|            let capability = capability
1793|                .as_str()
1794|                .ok_or_else(|| format!("grant entry for {key} contains a non-string capability"))?;
1795|            if capability.trim().is_empty() {
1796|                return Err(format!("grant entry for {key} contains an empty capability"));
1797|            }
1798|            if !unique.insert(capability) {
1799|                return Err(format!(
1800|                    "grant entry for {key} repeats capability {capability}"
1801|                ));
1802|            }
1803|        }
1804|        if let Some(alias) = entry.get("display_alias")
1805|            && !alias.is_string()
1806|        {
1807|            return Err(format!("display_alias for {key} must be a string"));
1808|        }
1809|        if key.starts_with('$') {
1810|            if entry.contains_key("groups") {
1811|                return Err(format!("group {key} cannot belong to another group"));
1812|            }
1813|            continue;
1814|        }
1815|        if key.is_empty() {
1816|            return Err("grant document contains an empty principal_id".to_string());
1817|        }
1818|        if let Some(groups) = entry.get("groups") {
1819|            let groups = groups
1820|                .as_array()
1821|                .ok_or_else(|| format!("groups for {key} must be an array"))?;
1822|            let mut seen = std::collections::HashSet::with_capacity(groups.len());
1823|            for group in groups {
1824|                let group = group
1825|                    .as_str()
1826|                    .ok_or_else(|| format!("groups for {key} contains a non-string"))?;
1827|                if !GRANT_GROUPS.contains(&group) || !entries.contains_key(group) {
1828|                    return Err(format!("principal {key} references unknown group {group}"));
1829|                }
1830|                if !seen.insert(group) {
1831|                    return Err(format!("principal {key} repeats group {group}"));
1832|                }
1833|            }
1834|        }
1835|    }
1836|    Ok(entries)
1837|}
