142|/// Read the identity's SID1 from its own device. It is read per call, so a
143|/// delivered or refreshed credential takes effect without a remount.
144|pub fn read_credential(path: &Path) -> Result<Vec<u8>, LungsError> {
145|    let file = std::fs::File::open(path)
146|        .map_err(|error| LungsError::Credential(format!("{}: {error}", path.display())))?;
147|    let metadata = file
148|        .metadata()
149|        .map_err(|error| LungsError::Credential(format!("{}: {error}", path.display())))?;
150|    if !metadata.is_file() || metadata.len() == 0 || metadata.len() > MAX_CREDENTIAL_BYTES {
151|        return Err(LungsError::Credential(format!(
152|            "{} is not a SID1 credential file",
153|            path.display()
154|        )));
155|    }
156|    let mut bytes = Vec::new();
157|    file.take(MAX_CREDENTIAL_BYTES + 1)
158|        .read_to_end(&mut bytes)
159|        .map_err(|error| LungsError::Credential(format!("{}: {error}", path.display())))?;
160|    if bytes.is_empty() || bytes.len() as u64 > MAX_CREDENTIAL_BYTES {
161|        return Err(LungsError::Credential(
